/* Read-only rendering of the exact private guidance frozen with a review. */
export function guidanceMarkup(packet,esc){
 const g=packet?.grounding||{},focus=packet?.outline_focus||{};
 const count=g.retrieved_count??g.coaching_records?.length??g.requirements?.length??0;
 return `<div class="sw-guidance"><p>${focus.selected?`Current idea: <strong>${esc(focus.selected.title)}</strong>. Your question defines the part to discuss.`:'The tutor will read the submitted passage without imposing every idea in the outline.'}</p><details><summary>${packet?.preview?'Guidance preview':'Guidance behind this reading'} · ${count} ${count===1?'record':'records'}</summary>${packet?.preview?'<p class="tiny">Preview for this stage and outline idea. Your question and submitted text determine the excerpts saved with the actual review.</p>':''}<p class="tiny">${esc(g.notice||'Current card and general writing guidance.')}</p>${packet?.context_selection?`<p class="tiny">${esc(packet.context_selection.notice)}</p>`:''}${(g.notices||[]).map(n=>`<p class="alert">${esc(n)}</p>`).join('')}${(g.conflicts||[]).length?`<p class="alert">Conflicting records: ${esc(g.conflicts.map(p=>p.join(' / ')).join('; '))}. Resolve them in Tutor knowledge.md.</p>`:''}${(g.coaching_records||g.requirements||[]).map(r=>`<article><p><strong>${esc(r.instruction||'')}</strong></p><p class="tiny">${esc(r.id)} · ${esc(r.status||'')} · ${esc(r.strength||'interpreted guidance')}</p>${(r.not_applicable_when||[]).length?`<p class="tiny">Do not apply this guidance when:</p><ul>${r.not_applicable_when.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${r.positive_example?`<p><strong>Example of applying this guidance:</strong> ${esc(r.positive_example)}</p>`:''}${(r.evidence||[]).map(e=>`<details><summary>${esc(e.title||e.source_id)} · ${esc(e.locator||'Source excerpt')}</summary><blockquote>${esc(e.quote||'')}</blockquote><p class="tiny">Source quotation matched locally. The interpretation is not new supervisor approval.</p></details>`).join('')}</article>`).join('')}${g.excluded_historical?.length?`<p class="tiny">${g.excluded_historical.length} historical, qualified or superseded records excluded.</p>`:''}</details></div>`;
}
export function adviceCheckMarkup(job,esc){
 const a=job?.alignment;if(!a)return '';
 const withheld=(a.items||[]).filter(x=>!x.retained);
 if(a.status==='not_requested')return `<div class="sw-alignment"><strong>${job.operation==='selected_passage_edit'?'Requested edit · your judgement comes next':'One local reading · your judgement comes next'}</strong><p>${esc(a.notice)}</p>${withheld.length?`<details><summary>Why some feedback was withheld</summary>${withheld.map(x=>`<p>${esc(x.reason||'')}${(x.comparison_flags||[]).map(f=>` ${esc(f.reason)}`).join('')}</p>`).join('')}</details>`:''}</div>`;
 return `<div class="sw-alignment"><strong>${a.status==='guidance_conflict'?'Guidance needs clarification':a.status==='unavailable'?'Advice check unavailable':withheld.length?'Some model feedback was withheld':'Advice comparison completed'}</strong><p>${esc(a.notice||'A second local-model check does not establish supervisor approval.')}</p>${withheld.length?`<details><summary>Why ${withheld.length} ${withheld.length===1?'item was':'items were'} withheld</summary>${withheld.map(x=>`<p><strong>${esc(x.id.startsWith('suggestion')?'Proposed wording':x.id.startsWith('next')?'Proposed next action':x.id.startsWith('strength')?'Proposed praise':'Proposed criticism')}</strong> · ${esc(x.reason||'')}</p>${(x.comparison_flags||[]).map(f=>`<p>${esc(f.reason)}</p>`).join('')}`).join('')}</details>`:''}<p class="tiny">${job.check_provenance?.model?(job.provenance?.model&&job.provenance.model!==job.check_provenance.model?'The first reading and the check use different local models.':'The first reading and this check use the same local model in separate calls.'):'No completed model comparison is recorded for this response.'} Shared errors remain possible.</p></div>`;
}
export function editAttemptsMarkup(job,esc){
 const attempts=job?.edit_attempts||[];
 if(attempts.length<2)return '';
 return `<details class="sw-edit-attempts"><summary>How this suggestion was revised · one correction attempt</summary><p>The first wording raised a text-preservation warning. The tutor could try once more using your original passage. These are model proposals, not changes to your draft.</p>${attempts.map((a,i)=>`<article><strong>${i?'Correction attempt':'First proposal'}</strong>${(a.proposal?.suggestions||[]).map(s=>`<blockquote>${esc(s.replacement||'')}</blockquote>`).join('')}${(a.flags||[]).map(f=>`<p>${esc(f.reason||'')}</p>`).join('')}${a.error?`<p>${esc(a.error)}</p>`:''}</article>`).join('')}</details>`;
}
export function reviewBasisMarkup(priority,job,esc){
 const g=job?.context?.grounding||{};
 const r=[...(g.coaching_records||g.requirements||[]),...(g.general_bases||[])].find(x=>x.id===priority.basis_id);
 return r?`<details><summary>Why this point applies</summary><p>${esc(r.instruction)}</p>${(r.evidence||[]).map(e=>`<p class="tiny">${esc(e.title)} · ${esc(e.locator)}</p><blockquote>${esc(e.quote)}</blockquote>`).join('')}<p class="tiny">A relevant rule can still be misapplied; compare the criticism with your actual words.</p></details>`:'';
}
